/**
 * Facts about a repository, and the predicates that decide from them whether a canon check applies (docs/CONSTITUTION.md, t=0).
 *
 * A check is never skipped on the word of the repository. Either it is applicable, configured and has checked something
 * (`checked > 0`), or kit.canon.json declares `notApplicable: { <check>: { predicate } }` AND the kit proves the predicate from the
 * files of the repository: a free-text reason waives nothing. A predicate that does not hold, a declaration for a check that is
 * configured, and a check that is applicable but not configured all fail.
 *
 *   repoFacts(root, canon) → { vendoredKit, persianSite, persianText, code, data, generated, diagrams, colourSources,
 *                              englishContent, openapi, routes }   (booleans; computed once per run; conceptSeries: concepts.config.json exists)
 *   PREDICATES[id] → { checks: [names], fact: sentence, holds(facts) }
 */
import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { execFileSync } from "node:child_process";
import { globRe, isGlob, isTestFile, walk } from "./files.js";
import { gitEnv } from "../git.js";
import { scanDeployments } from "../wrangler-config.js";
import { DEFAULT_VENDOR_PATH, snapshotRoots } from "../vendor-path.js";

const CODE = /\.(m?js|cjs|tsx?|jsx)$/;
const ARABIC = /[\p{Script=Arabic}]{2,}\s+[\p{Script=Arabic}]{2,}/u;
const GENERATED = /\b(generated by|do not edit|auto-?generated|DO NOT EDIT)\b/i;
const LOCALE_FA = /\b(?:locale|locales|lang|language|defaultLocale)\b[^\n]{0,60}["']fa(?:-IR)?["']/;
const readHead = (root, f, n = 600) => { try { return readFileSync(join(root, f), "utf8").slice(0, n); } catch { return ""; /* an unreadable file has no head: the facts read from it stay absent */ } };

/** The deployment scan with the repository's reviewed not-deployed allow-list (canon.allow.json). */
export function deployScan(root, canon = {}) {
  const f = join(root, canon.hardcoding?.allow || "canon.allow.json");
  let allow = [];
  // a malformed allow-list is reported by the canon's own validation; here it allows nothing (fail closed: more is deployed, not less)
  if (existsSync(f)) { try { const e = JSON.parse(readFileSync(f, "utf8"))?.entries; allow = Array.isArray(e) ? e.filter((x) => x && typeof x === "object") : []; } catch { /* unparseable input counts as absent, never as a valid value */ allow = []; } }
  return scanDeployments(root, { allow });
}

/**
 * The files whose text says nothing about the repository's own content: the built output the canon declares (tokens.generated: a directory or
 * a glob) and whatever git ignores. A built site carries the kit's own browser scripts (a formatter with Persian digit tables), so scanning it
 * made every English-only site "have Persian text". Without git (a copy, a test directory) only the declared paths apply.
 */
export function generatedFiles(root, files, canon = {}) {
  const declared = (canon.tokens?.generated || []).map((p) => (isGlob(p) ? { re: globRe(p) } : { dir: p.replace(/\/+$/, "") }));
  const isDeclared = (f) => declared.some((d) => (d.re ? d.re.test(f) : f === d.dir || f.startsWith(`${d.dir}/`)));
  const out = new Set(files.filter(isDeclared));
  if (existsSync(join(root, ".git")) && files.length) {
    try {
      const listed = execFileSync("git", ["check-ignore", "--stdin", "-z"], { cwd: root, input: `${files.join("\0")}\0`, encoding: "utf8", maxBuffer: 64 << 20, stdio: ["pipe", "pipe", "ignore"], env: gitEnv() });
      for (const f of listed.split("\0").filter(Boolean)) out.add(f);
    } catch (e) {
      // git check-ignore exits 1 when nothing is ignored; any other failure (no git binary) leaves only the declared paths
      if (e?.status !== 1) console.error("[canon] persian fact: gitignored paths could not be read, only tokens.generated is skipped:", String(e?.message || e).split("\n")[0]);
    }
  }
  return out;
}

/** Facts, read from the repository's files only (never from kit.canon.json's own claims). */
export function repoFacts(root, canon = {}) {
  const files = walk(root).filter((f) => !f.startsWith(".git/"));
  // A vendored Kit is a dependency, not the project's own content. In particular its fa locale and
  // examples must not force an English-only site to declare Persian copy. The vendor proof remains
  // independent (vendoredKit below), including snapshots at the default path after moving vendor.path.
  const vendor = snapshotRoots(canon.vendor);
  const isVendor = (f) => vendor.some(({ snapshot, manifest }) => f === manifest || f === snapshot || f.startsWith(`${snapshot}/`));
  const own = files.filter((f) => !f.startsWith("sdk/") && !isVendor(f));
  const nonTest = own.filter((f) => !isTestFile(f));
  const rootConfigs = ["kit.config.js", "site.config.js", "comms.config.js", "podcast.config.json", "kit.config.json"].filter((f) => existsSync(join(root, f)));
  const siteDirs = ["site", "public", "dist", "locales"].filter((d) => existsSync(join(root, d)));
  const persianSite = rootConfigs.some((f) => LOCALE_FA.test(readHead(root, f, 200000)))
    || own.some((f) => /^locales\/fa(\/|\.)/.test(f))
    || own.some((f) => siteDirs.includes(f.split("/")[0]) && /\.html?$/.test(f) && /<html[^>]*\blang="fa/i.test(readHead(root, f, 400)));
  const builtOutput = generatedFiles(root, nonTest, canon);
  const textual = nonTest.filter((f) => !builtOutput.has(f) && /\.(md|json|html?|txt|m?js)$/.test(f) && !/(^|\/)(package-lock\.json|[^/]*\.lock\.json)$/.test(f));
  const persianText = existsSync(join(root, "persian.config.json")) || persianSite || textual.some((f) => ARABIC.test(readFileSync(join(root, f), "utf8")));
  const jsonData = nonTest.filter((f) => f.endsWith(".json") && !/(^|\/)(package(-lock)?|tsconfig[^/]*|jsconfig|\.eslintrc)\.json$/.test(f) && !/^(kit\.canon|canon\.allow|kit\.sdk)\.json$/.test(f));
  const generated = own.some((f) => /\.generated\.|(^|\/)forge\.manifest\.json$|\.manifest\.json$/.test(f))
    || textual.some((f) => GENERATED.test(readHead(root, f)));
  const markdown = own.filter((f) => f.endsWith(".md"));
  // English prose: a Markdown file with at least 20 Latin words and little Arabic script
  const english = (f) => { const t = readFileSync(join(root, f), "utf8").replace(/```[\s\S]*?```/g, ""); return (t.match(/\b[A-Za-z]{2,}\b/g) || []).length >= 20 && (t.match(/[\p{Script=Arabic}]/gu) || []).length < t.length * 0.2; };
  return {
    conceptSeries: existsSync(join(root, "concepts.config.json")),
    // every snapshot root (the configured vendor.path and the default): moving vendor.path never waives the proof of a snapshot left behind
    vendoredKit: snapshotRoots(canon.vendor).some((r) => existsSync(join(root, r.snapshot)) || existsSync(join(root, r.manifest))),
    persianSite,
    persianText,
    code: nonTest.some((f) => CODE.test(f)),
    data: jsonData.length > 0 || own.some((f) => /(^|\/)[^/]*\.config\.m?js$/.test(f)),
    generated,
    diagrams: own.some((f) => f.startsWith("docs/diagrams/")) || markdown.some((f) => /^[ \t]*(```|~~~)[ \t]*mermaid/im.test(readFileSync(join(root, f), "utf8"))),
    colourSources: own.some((f) => /\.(css|html?|svg|tsx|jsx)$/.test(f)),
    englishContent: markdown.some(english),
    openapi: (canon.contracts || []).some((c) => c.type === "openapi") || own.some((f) => /(^|\/)openapi[^/]*\.json$/.test(f)),
    // by content, every name and directory, deploy commands too; an unreadable candidate counts (fail closed) (wrangler-config.js)
    workers: ((d) => d.deployed.length > 0 || d.commands.length > 0 || d.problems.length > 0)(deployScan(root, canon)),
    routes: nonTest.some((f) => /\.(m?js|ts)$/.test(f) && /["'`]\/(?:api\/|mcp\b)/.test(readFileSync(join(root, f), "utf8"))),
  };
}

/** The predicates a notApplicable declaration may name (kit.canon.json schema enum). Each is proven from facts. */
export const PREDICATES = {
  "no-data-files": { checks: ["schemas"], fact: "the repository has no JSON data file and no *.config.js module to validate", holds: (f) => !f.data },
  "no-http-surface": { checks: ["contracts"], fact: "no source file names an /api/ or /mcp route and no OpenAPI document exists", holds: (f) => !f.routes && !f.openapi },
  "no-openapi-contract": { checks: ["sdk"], fact: "the repository has no OpenAPI contract to generate an SDK from", holds: (f) => !f.openapi },
  "no-source-code": { checks: ["hardcoding"], fact: "the repository has no JavaScript or TypeScript source outside its tests", holds: (f) => !f.code },
  "no-generated-artefacts": { checks: ["freshness"], fact: "no file is generated (no *.generated.*, no manifest, no 'generated by' or 'do not edit' header)", holds: (f) => !f.generated },
  "no-diagrams": { checks: ["diagrams"], fact: "the repository has no docs/diagrams directory and no Mermaid block in any Markdown file", holds: (f) => !f.diagrams },
  "no-persian-site": { checks: ["digits"], fact: "the repository renders no Persian site (no fa locale in a root config, no locales/fa, no lang=\"fa\" page)", holds: (f) => !f.persianSite },
  "no-persian-content": { checks: ["persian"], fact: "the repository has no persian.config.json and no Persian text", holds: (f) => !f.persianText },
  "no-vendored-kit": { checks: ["vendor"], fact: `the repository has no vendored kit snapshot or manifest (kit.canon.json vendor.path, or ${DEFAULT_VENDOR_PATH})`, holds: (f) => !f.vendoredKit },
  "no-english-content": { checks: ["spelling"], fact: "the repository has no English Markdown prose (a file of 20 or more Latin words that is not mostly Arabic script)", holds: (f) => !f.englishContent },
  "no-deployed-workers": { checks: ["resilience", "release"], fact: "the repository deploys no Worker: no wrangler config and no deploy command (package.json scripts, workflows) found by content, outside the vendored kit and the reviewed not-deployed entries of canon.allow.json", holds: (f) => !f.workers },
  "no-colour-sources": { checks: ["tokens"], fact: "the repository has no CSS, HTML, SVG, JSX or TSX file", holds: (f) => !f.colourSources },
};

/** Checks that no declaration can waive: they run everywhere. */
export const ALWAYS = ["claude", "enforcement", "findings"];
